import{_ as e,o as t,c as r,a3 as s}from"./chunks/framework.Cj_fzHAr.js";const u=JSON.parse('{"title":"Rol: Trabajador","description":"","frontmatter":{},"headers":[],"relativePath":"roles/trabajador.md","filePath":"roles/trabajador.md"}'),o={name:"roles/trabajador.md"};function i(d,a,n,l,c,m){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="rol-trabajador" tabindex="-1">Rol: Trabajador <a class="header-anchor" href="#rol-trabajador" aria-label="Permalink to &quot;Rol: Trabajador&quot;">​</a></h1><p>El <strong>trabajador</strong> es la persona en terreno. Su interacción con la plataforma se centra en firmar lo que se le asigna y registrar su asistencia a actividades.</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><ul><li>Firmar los documentos que se le asignan (recepción de reglamento, EPP, etc.).</li><li>Asistir y firmar charlas y capacitaciones.</li><li>Reportar condiciones inseguras (hallazgos).</li><li>Responder encuestas y declaraciones de salud.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Acceso</th></tr></thead><tbody><tr><td>Dashboard</td><td>👁 Sus pendientes y actividades</td></tr><tr><td>Obras</td><td>✗ Sin acceso</td></tr><tr><td>Documentos</td><td>👁 Los asignados a él</td></tr><tr><td>Firmas</td><td>✓ Firma de lo que le corresponde</td></tr><tr><td>Incidentes</td><td>👁 Reportar hallazgos</td></tr><tr><td>Actividades</td><td>👁 Asistir y firmar</td></tr><tr><td>Encuestas</td><td>👁 Responder las asignadas</td></tr><tr><td>Asistente IA</td><td>✗ Sin acceso</td></tr><tr><td>Personas</td><td>✗ Sin acceso</td></tr><tr><td>Bandeja de Entrada</td><td>✓ Recibir notificaciones</td></tr><tr><td>Tenants</td><td>✗ Sin acceso</td></tr></tbody></table><h2 id="acceso-web-opcional" tabindex="-1">Acceso web opcional <a class="header-anchor" href="#acceso-web-opcional" aria-label="Permalink to &quot;Acceso web opcional&quot;">​</a></h2><p>No todos los trabajadores tienen acceso web. Según <code>tieneAccesoWeb</code>:</p><ul><li><strong>Con acceso web</strong>: inicia sesión, ve sus pendientes y firma desde su dispositivo.</li><li><strong>Sin acceso web</strong>: no tiene <code>passwordHash</code>, pero sí <code>pinHash</code> para firmar en el dispositivo del supervisor en terreno.</li></ul><p>Ver detalle en <a href="/manual/modulos/personas.html">Personas</a>.</p><h2 id="firma-con-pin" tabindex="-1">Firma con PIN <a class="header-anchor" href="#firma-con-pin" aria-label="Permalink to &quot;Firma con PIN&quot;">​</a></h2><p>El trabajador firma con su <strong>PIN personal</strong>. La firma queda registrada de forma inmutable con PIN + IP + timestamp. Puede firmar también <strong>sin conexión</strong>, sincronizando después. Ver <a href="/manual/modulos/firmas.html">Firmas</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>La validez del PIN como firma electrónica está en consulta legal. Ver <a href="/manual/ds44/firmas-digitales.html">Firmas digitales y DS44</a>.</p></div>',13)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
